float sdMoon(in SDFG_VEC pos, in float ra, in float rb, in float cutOffset)
{
    vec2 p = pos.xz;

    // Luk: different parametrisation of this offset
    //float d = cutOffset;
    float d = -mix(max(ra - rb, rb - ra), ra + rb, cutOffset);

// Luk: Comparison with boolean operators:
//    float d1 = length(p) - ra;
//    float d2 = length(p-vec2(d, 0.)) - rb;
//    return max(d1, -d2);

    p.y = abs(p.y);

    float a = (ra*ra - rb*rb + d*d)/(2.0*d);
    float b = sqrt(max(ra*ra-a*a,0.0));
    if( d*(p.x*b-p.y*a) > d*d*max(b-p.y,0.0) )
    {
        return length(p-vec2(a,b));
    }

    return max( (length(p          )-ra),
               -(length(p-vec2(d,0))-rb));

}
